-- ========================================================
-- NetZeroCalc (e-Credits) Supabase Database Schema & Seed
-- ========================================================

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

CREATE TABLE IF NOT EXISTS public.projects (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID,
    project_name TEXT NOT NULL,
    company_name TEXT,
    standard TEXT DEFAULT 'ISO 14064-1 & Scope 1-3',
    total_footprint NUMERIC(12, 4) DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE IF NOT EXISTS public.bom_items (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    project_id UUID REFERENCES public.projects(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    qty NUMERIC(12, 4) NOT NULL,
    unit VARCHAR(50) NOT NULL,
    process TEXT,
    ef NUMERIC(12, 6) NOT NULL,
    scope VARCHAR(50) DEFAULT 'Scope 3',
    risk VARCHAR(20) DEFAULT 'LOW',
    status VARCHAR(50) DEFAULT 'Auto-Matched',
    approved BOOLEAN DEFAULT FALSE,
    ter NUMERIC(3, 1) DEFAULT 1.0,
    ger NUMERIC(3, 1) DEFAULT 1.0,
    tir NUMERIC(3, 1) DEFAULT 1.0,
    auditor_notes TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE IF NOT EXISTS public.india_ghg_factors (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    lookup_key VARCHAR(255) UNIQUE NOT NULL,
    emission_factor NUMERIC(12, 6) NOT NULL,
    source_notes TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.bom_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.india_ghg_factors ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow public access to projects" ON public.projects FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public access to bom_items" ON public.bom_items FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public access to india_ghg_factors" ON public.india_ghg_factors FOR ALL USING (true) WITH CHECK (true);

